package com.wizzadrds.theworldremembers.knowledge; import org.junit.jupiter.api.Test; import java.util.UUID; import static org.junit.jupiter.api.Assertions.*; class KnowledgeFactTest{@Test void directKnowledgeOutranksRumor(){var id=UUID.randomUUID();var subject=UUID.randomUUID();var rumor=new KnowledgeFact(id,subject,"NPC_DIED",UUID.randomUUID(),KnowledgeOrigin.RUMORED,20,1,1);var direct=new KnowledgeFact(id,subject,"NPC_DIED",id,KnowledgeOrigin.DIRECT,100,1,1);assertEquals(KnowledgeOrigin.DIRECT,direct.origin());assertTrue(direct.confidence()>rumor.confidence());}@Test void confidenceDegradesWithTime(){var f=new KnowledgeFact(UUID.randomUUID(),UUID.randomUUID(),"NPC_DIED",UUID.randomUUID(),KnowledgeOrigin.RUMORED,80,1,1);assertEquals(79,f.degrade(1201).confidence());}}
